package com.customrpg.managers;

import com.customrpg.CustomRPG;
import com.customrpg.talents.*;
import com.customrpg.utils.*;
import com.customrpg.vfx.*;
import com.customrpg.vfx.VfxMath.V;
import org.bukkit.*;
import org.bukkit.attribute.*;
import org.bukkit.entity.*;
import org.bukkit.event.*;
import org.bukkit.event.entity.*;
import org.bukkit.event.player.*;
import org.bukkit.scheduler.BukkitTask;
import org.bukkit.util.Vector;
import java.util.*;

/** One bounded combat clock. Pure visual sampling never decides damage, crossing, curse or movement. */
public final class DarkTalentSkills implements Listener {
    private static final NamespacedKey SPEED=new NamespacedKey("customrpg","dark_slow");
    interface Motion {void set(LivingEntity target,double percent);void clear(LivingEntity target);}
    private final CustomRPG plugin;private final ExpandedTalentSkills combat;private final Motion motion;private final DarkBrands brands=new DarkBrands();
    private long tick;private BukkitTask task;
    private static final class Cast {final Player source;final Talent talent;final int rank;final Location origin;final Vector facing;final Set<UUID> stamped=new HashSet<>();Cast(Player p,Talent t,int rank){source=p;talent=t;this.rank=rank;origin=p.getLocation().clone();facing=flat(p);}}
    private record Job(Cast cast,long at,Runnable action){}
    private record Key(UUID owner,UUID target){}
    private record CurseKey(UUID owner,UUID target,DarkControlEvent.Kind kind,double amount){}
    private record Curse(Cast cast,LivingEntity target,DarkControlEvent.Kind kind,double amount,long until){}
    private record Follow(Cast cast,LivingEntity target,Location origin,Vector facing,DarkVfx.Anchor anchor,UUID visual,long until){}
    private static final class Curtain {final Cast cast;final Location center;final long until;final Set<UUID> hit=new HashSet<>();final DarkVfx.Anchor anchor=new DarkVfx.Anchor();Curtain(Cast c,Location at,long until){cast=c;center=at;this.until=until;}}
    private static final class Echo {final Cast cast;final LivingEntity target;final long until;final DarkVfx.Anchor anchor=new DarkVfx.Anchor();double damage;Echo(Cast c,LivingEntity t,long until){cast=c;target=t;this.until=until;}}
    private static final class Guard {final Cast cast;final long until;final DarkVfx.Anchor anchor=new DarkVfx.Anchor();boolean reserved;Guard(Cast c,long until){cast=c;this.until=until;}}
    private record Summon(Cast cast,long until,DarkVfx.Anchor anchor){}
    private record Absorbed(Guard guard,LivingEntity attacker,double before){}
    private record Hit(boolean accepted,double lifeLost){}
    private final List<Job> jobs=new ArrayList<>();private final List<Curtain> curtains=new ArrayList<>();private final Map<Key,Echo> echoes=new HashMap<>();private final Map<UUID,Guard> guards=new HashMap<>();private final Map<UUID,Summon> summons=new HashMap<>();
    private final Map<CurseKey,Curse> curses=new HashMap<>();private final Map<UUID,LivingEntity> slowed=new HashMap<>();private final Map<UUID,Double> applied=new HashMap<>();private final List<Follow> following=new ArrayList<>();private final Map<Key,Follow> glyphs=new HashMap<>();
    private final Map<UUID,Set<UUID>> visuals=new HashMap<>();private final Map<EntityDamageEvent,Absorbed> pending=new IdentityHashMap<>();private final Set<UUID> stepping=new HashSet<>();
    public DarkTalentSkills(CustomRPG p,ExpandedTalentSkills c){this(p,c,null);}
    DarkTalentSkills(CustomRPG p,ExpandedTalentSkills c,Motion motion){plugin=p;combat=c;this.motion=motion!=null?motion:new Motion(){
        public void clear(LivingEntity t){var a=t.getAttribute(Attribute.MOVEMENT_SPEED);if(a!=null)for(var m:new ArrayList<>(a.getModifiers()))if(m.getKey().equals(SPEED))a.removeModifier(m);}
        public void set(LivingEntity t,double percent){clear(t);var a=t.getAttribute(Attribute.MOVEMENT_SPEED);if(a!=null&&percent>0)a.addTransientModifier(new AttributeModifier(SPEED,-percent,AttributeModifier.Operation.MULTIPLY_SCALAR_1));}
    };}
    public void start(){if(task==null)task=plugin.getServer().getScheduler().runTaskTimer(plugin,this::tick,1,1);}
    public boolean internalStep(Player p){return stepping.contains(p.getUniqueId());}
    public static void validate(Talent t){
        if(t.getBranch()!=TalentBranch.DARK)throw new IllegalArgumentException("Not a Dark talent");
        var s=DarkSkill.of(t.getId());
        if(s==null){if(t.getType()!=TalentType.PASSIVE||!Set.of("dark_affinity","dark_resilience","life_leech").contains(t.getId()))throw new IllegalArgumentException("Unsupported Dark node");}
        else if(t.getType()!=TalentType.ACTIVE||t.getMaxLevel()!=3||t.getGuiSlot()!=s.slot||t.getPointsPerLevel()!=1||t.getManaCost()!=s.mana||t.getCooldown()!=s.cooldown||t.getHpCost()!=0)throw new IllegalArgumentException("Invalid Dark layout/cost");
        if(t.getMaxLevel()<1||t.getMaxLevel()>3||t.getGuiSlot()<0||t.getGuiSlot()>=53)throw new IllegalArgumentException("Invalid Dark levels/slot");
        for(int rank=1;rank<=t.getMaxLevel();rank++){var d=t.getLevelData(rank);if(d==null||d.effects.values().stream().anyMatch(v->!Double.isFinite(v)))throw new IllegalArgumentException("Invalid Dark data");if(s!=null&&(!d.scaling.isEmpty()||!d.effects.keySet().equals(Set.of("baseDamage","range"))||t.getEffectDouble(rank,"range",-1)!=s.range||t.getEffectDouble(rank,"baseDamage",-1)<0||t.getEffectDouble(rank,"baseDamage",-1)>32))throw new IllegalArgumentException("Unsafe Dark effects");}
    }
    private static Vector flat(Player p){var d=p.getLocation().getDirection().setY(0);return d.lengthSquared()<.001?new Vector(0,0,1):d.normalize();}
    private Vector facing(LivingEntity t){var d=t.getLocation().getDirection().setY(0);return d.lengthSquared()<.001?new Vector(0,0,1):d.normalize();}
    private boolean valid(Cast c){var p=c.source;if(!p.isOnline()||p.isDead()||p.getGameMode()==GameMode.SPECTATOR||!p.getWorld().equals(c.origin.getWorld())||combat.protectedAt(p.getLocation()))return false;var pt=plugin.getTalentManager().getPlayerTalents(p);return pt.getTalentLevel(c.talent.getId())>0&&(DarkSkill.ultimate(c.talent.getId())?c.talent.getId().equals(pt.getUltimateSkill()):Arrays.asList(pt.getSelectedSkills()).contains(c.talent.getId()));}
    private V v(Location at){return new V(at.getX(),at.getY(),at.getZ());}
    private V local(Location origin,Vector dir,Location at){var f=VfxMath.Frame.facing(v(origin),new V(dir.getX(),dir.getY(),dir.getZ()),Math.toRadians(origin.getYaw()));var d=v(at).sub(v(origin));return new V(d.dot(f.right()),d.dot(f.up()),d.dot(f.forward()));}
    private UUID show(Cast c,Location at,Vector dir,VfxRuntime.Effect effect,LivingEntity target){var service=plugin.getVfxService();if(service==null)return null;UUID id=service.dark(c.source,c.talent.getId(),at,dir,effect,VfxRuntime.Mode.COMBAT,target,0);if(id!=null)visuals.computeIfAbsent(c.source.getUniqueId(),ignored->new HashSet<>()).add(id);return id;}
    private void stop(UUID id){if(id!=null&&plugin.getVfxService()!=null)plugin.getVfxService().runtime().cancelInstance(id);}
    private Follow follow(Cast c,LivingEntity target,DarkVfx.Anchor a,VfxRuntime.Effect effect,int ticks){Location origin=target.getLocation().clone();Vector dir=facing(target);UUID id=show(c,origin,dir,effect,target);var f=new Follow(c,target,origin,dir,a,id,tick+ticks);if(id!=null&&following.size()<1024)following.add(f);return f;}
    private void later(Cast c,int ticks,Runnable action){jobs.add(new Job(c,tick+ticks,action));}
    private boolean loaded(Location from,Vector direction,double distance){var dir=direction.clone().normalize();for(double d=0;d<=distance+.5;d+=.5){var at=from.clone().add(dir.clone().multiply(Math.min(distance,d)));if(!at.getWorld().isChunkLoaded(at.getBlockX()>>4,at.getBlockZ()>>4))return false;}return true;}
    private boolean clear(Location from,Location to){if(!from.getWorld().equals(to.getWorld()))return false;var dir=to.toVector().subtract(from.toVector());double d=dir.length();return d<.1||loaded(from,dir,d)&&from.getWorld().rayTraceBlocks(from,dir.normalize(),Math.max(0,d-.1),FluidCollisionMode.NEVER,true)==null;}
    private Location ground(Location at){var w=at.getWorld();if(!w.isChunkLoaded(at.getBlockX()>>4,at.getBlockZ()>>4))return null;for(int y=at.getBlockY()+1;y>=at.getBlockY()-3;y--){if(y<w.getMinHeight()||y+2>=w.getMaxHeight())continue;var b=w.getBlockAt(at.getBlockX(),y,at.getBlockZ());if(!b.isPassable()&&!b.isLiquid()&&w.getBlockAt(at.getBlockX(),y+1,at.getBlockZ()).isPassable())return new Location(w,at.getX(),b.getBoundingBox().getMaxY()+.03,at.getZ(),at.getYaw(),0);}return null;}
    private Location aimGround(Player p,int range){var eye=p.getEyeLocation();if(!loaded(eye,eye.getDirection(),range))return null;var ray=p.getWorld().rayTraceBlocks(eye,eye.getDirection(),range,FluidCollisionMode.NEVER,true);var at=ground(ray==null?p.getLocation().add(flat(p).multiply(range)):ray.getHitPosition().toLocation(p.getWorld()));return at!=null&&at.distanceSquared(eye)<=(range+.5)*(range+.5)&&clear(eye,at.clone().add(0,.1,0))&&!combat.protectedAt(at)?at:null;}
    private LivingEntity aim(Player p,int range){return loaded(p.getEyeLocation(),p.getEyeLocation().getDirection(),range)?combat.aim(p,range):null;}
    private List<LivingEntity> enemies(Cast c,Location center,double radius){if(!center.getWorld().isChunkLoaded(center.getBlockX()>>4,center.getBlockZ()>>4))return List.of();return center.getWorld().getNearbyEntities(center,radius,4,radius).stream().filter(e->e instanceof LivingEntity).map(e->(LivingEntity)e).filter(e->e.getLocation().distanceSquared(center)<=radius*radius&&combat.enemy(c.source,e)&&clear(center.clone().add(0,.5,0),e.getEyeLocation())).limit(24).toList();}
    private void curse(Cast c,LivingEntity t,DarkControlEvent.Kind kind,double amount,int duration){if(duration<=0||t.isDead()||!t.isValid())return;var key=new CurseKey(c.source.getUniqueId(),t.getUniqueId(),kind,amount);if(curses.size()>=4096&&!curses.containsKey(key))return;var event=new DarkControlEvent(c.source,t,kind,amount,duration);plugin.getServer().getPluginManager().callEvent(event);if(!event.isCancelled())curses.put(key,new Curse(c,t,kind,amount,tick+duration));}
    public boolean cleanseOrdinarySlow(LivingEntity target){var key=curses.entrySet().stream().filter(e->e.getValue().target.equals(target)&&e.getValue().kind==DarkControlEvent.Kind.SLOW&&e.getValue().amount<1&&e.getValue().until>tick).map(Map.Entry::getKey).findFirst().orElse(null);if(key==null)return false;curses.remove(key);applySlows();return true;}
    private void applySlows(){var values=new HashMap<UUID,Double>();for(var c:curses.values())if(c.kind==DarkControlEvent.Kind.SLOW){slowed.put(c.target.getUniqueId(),c.target);values.merge(c.target.getUniqueId(),c.amount,Math::max);}for(var id:new ArrayList<>(slowed.keySet())){double n=values.getOrDefault(id,0.0);if(n!=applied.getOrDefault(id,-1.0)){motion.set(slowed.get(id),n);applied.put(id,n);}if(n==0){slowed.remove(id);applied.remove(id);}}}
    private double reduction(LivingEntity target,DarkControlEvent.Kind kind){return curses.values().stream().filter(c->c.kind==kind&&c.target.equals(target)&&tick<c.until&&valid(c.cast)&&c.cast.source.getWorld().equals(target.getWorld())).mapToDouble(Curse::amount).max().orElse(0);}
    public double outgoingMultiplier(LivingEntity attacker){return attacker==null?1:1-reduction(attacker,DarkControlEvent.Kind.OUTGOING_DAMAGE);}
    /** Invoked after the existing heal caps/budgets, including potion healing and non-player regeneration. */
    public void weakenHealing(EntityRegainHealthEvent e){if(!e.isCancelled()&&e.getEntity() instanceof LivingEntity target)e.setAmount(e.getAmount()*(1-reduction(target,DarkControlEvent.Kind.HEALING)));}
    private void brandVisual(Cast c,LivingEntity target){var key=new Key(c.source.getUniqueId(),target.getUniqueId());var old=glyphs.remove(key);if(old!=null){old.anchor.layers=0;stop(old.visual);following.remove(old);}int layers=brands.layers(key.owner,key.target,tick);if(layers==0||glyphs.size()>=1024)return;var a=new DarkVfx.Anchor();a.layers=layers;var f=follow(c,target,a,new DarkVfx.Brand(a),140);glyphs.put(key,f);}
    private Hit raw(Cast c,LivingEntity target,double amount,boolean periodic,boolean followUp,boolean normalized){if(amount<=0||!valid(c)||!combat.enemy(c.source,target))return new Hit(false,0);double hp=MobManager.getVirtualCurrentHP(target),before=hp+target.getAbsorptionAmount();if(followUp)SkillDamageGuard.damageFollowUp(target,amount,c.source,periodic);else if(normalized)SkillDamageGuard.damageNormalizedPeriodic(target,amount,c.source);else if(periodic)SkillDamageGuard.damagePeriodic(target,amount,c.source);else SkillDamageGuard.damage(target,amount,c.source);return new Hit(MobManager.getVirtualCurrentHP(target)+target.getAbsorptionAmount()<before,Math.max(0,hp-MobManager.getVirtualCurrentHP(target)));}
    private boolean hit(Cast c,LivingEntity target,double damage,boolean direct,boolean followUp,boolean normalized){
        boolean ready=direct&&brands.ready(c.source.getUniqueId(),target.getUniqueId(),tick);var result=raw(c,target,damage,!direct,followUp,normalized);if(!result.accepted)return false;
        if(direct&&result.lifeLost>0){var echo=echoes.get(new Key(c.source.getUniqueId(),target.getUniqueId()));if(echo!=null&&tick<echo.until){echo.damage=Math.min(14,echo.damage+result.lifeLost);echo.anchor.energy=echo.damage/14;echo.anchor.cracks=Math.min(8,echo.anchor.cracks+1);}}
        boolean burst=false;
        if(ready&&!target.isDead()&&raw(c,target,3,true,true,false).accepted){burst=brands.consume(c.source.getUniqueId(),target.getUniqueId(),tick);if(burst){curse(c,target,DarkControlEvent.Kind.HEALING,.15,80);show(c,target.getLocation(),facing(target),new DarkVfx.BrandBurst(),target);}}
        if(!target.isDead()&&c.stamped.add(target.getUniqueId())&&!burst)brands.add(c.source.getUniqueId(),target.getUniqueId(),tick);
        if(!target.isDead())brandVisual(c,target);return true;
    }
    private Location blinkEnd(Player p){var eye=p.getEyeLocation();Vector dir=eye.getDirection();if(!loaded(eye,dir,6))return null;Location last=null;for(double d=.25;d<=6;d+=.25){var sample=p.getLocation().add(dir.clone().multiply(d));var at=ground(sample);if(at==null||Math.abs(at.getY()-sample.getY())>1.1||!safe(p,at)||!clear(eye,at.clone().add(0,p.getEyeHeight(),0)))break;last=at;}return last!=null&&last.distanceSquared(p.getLocation())>=.25&&last.distanceSquared(p.getLocation())<=36.5?last:null;}
    private boolean safe(Player p,Location at){var w=at.getWorld();for(int x=(int)Math.floor(at.getX()-.4)>>4;x<=((int)Math.floor(at.getX()+.4)>>4);x++)for(int z=(int)Math.floor(at.getZ()-.4)>>4;z<=((int)Math.floor(at.getZ()+.4)>>4);z++)if(!w.isChunkLoaded(x,z))return false;return w.getWorldBorder().isInside(at)&&!combat.protectedAt(at)&&!p.collidesAt(at)&&!at.getBlock().isLiquid()&&!at.clone().add(0,1,0).getBlock().isLiquid();}
    private boolean noTarget(Player p){p.sendMessage("§c請瞄準射程內可見敵人或安全地面，換影步不可穿牆。");return false;}
    public boolean cast(Player p,Talent talent,int rank){var s=DarkSkill.of(talent.getId());if(s==null)return false;var c=new Cast(p,talent,rank);if(!valid(c)||jobs.size()>192)return false;double base=talent.getEffectDouble(rank,"baseDamage",s.damage);
        switch(s){
            case REND->{var target=aim(p,12);if(target==null)return noTarget(p);var a=new DarkVfx.Anchor();follow(c,target,a,new DarkVfx.Rend(a),19);boolean[] first={false};later(c,5,()->first[0]=hit(c,target,base,true,false,false));later(c,9,()->hit(c,target,base*4/3,true,first[0],false));}
            case STITCH->{var target=aim(p,11);if(target==null)return noTarget(p);if(hit(c,target,base,true,false,false)&&!target.isDead()){curse(c,target,DarkControlEvent.Kind.SLOW,.25,80);curse(c,target,DarkControlEvent.Kind.OUTGOING_DAMAGE,.15,80);var a=new DarkVfx.Anchor();follow(c,target,a,new DarkVfx.Stitch(a),88);}}
            case STEP->{Location destination=blinkEnd(p);if(destination==null)return noTarget(p);show(c,c.origin,c.facing,new DarkVfx.Transposition(local(c.origin,c.facing,destination)),null);later(c,9,()->{if(p.getLocation().distanceSquared(c.origin)>2.25||!safe(p,destination)||!clear(p.getEyeLocation(),destination.clone().add(0,p.getEyeHeight(),0)))return;stepping.add(p.getUniqueId());try{p.teleport(destination,PlayerTeleportEvent.TeleportCause.PLUGIN);}finally{stepping.remove(p.getUniqueId());}});}
            case CURTAIN->{if(curtains.size()>=64)return false;Location center=ground(p.getLocation().add(c.facing.clone().multiply(5)));if(center==null||combat.protectedAt(center)||!clear(p.getEyeLocation(),center.clone().add(0,1.5,0)))return noTarget(p);var field=new Curtain(c,center,tick+100);curtains.add(field);show(c,center,c.facing,new DarkVfx.Curtain(field.anchor),null);}
            case ECHO->{var target=aim(p,10);if(target==null||echoes.size()>=128)return noTarget(p);var key=new Key(p.getUniqueId(),target.getUniqueId());var state=new Echo(c,target,tick+80);echoes.put(key,state);follow(c,target,state.anchor,new DarkVfx.Echo(state.anchor,false),100);later(c,80,()->{if(echoes.get(key)!=state)return;echoes.remove(key);hit(c,target,Math.min(5,state.damage*.35),false,false,true);});}
            case SERVANT->{if(summons.size()>=64&&!summons.containsKey(p.getUniqueId()))return false;var a=new DarkVfx.Anchor();var summon=new Summon(c,tick+120,a);summons.put(p.getUniqueId(),summon);follow(c,p,a,new DarkVfx.Servant(a,false),126);for(int i=1;i<=4;i++)later(c,i*24,()->{if(summons.get(p.getUniqueId())!=summon)return;var target=enemies(c,p.getLocation(),6).stream().min(Comparator.comparingDouble(e->e.getLocation().distanceSquared(p.getLocation()))).orElse(null);if(target!=null&&hit(c,target,base,true,false,false)){a.end=local(p.getLocation(),c.facing,target.getEyeLocation());a.pulse=8;}});}
            case FRACTURE->{var guard=new Guard(c,tick+80);guards.put(p.getUniqueId(),guard);follow(c,p,guard.anchor,new DarkVfx.Fracture(guard.anchor,false),96);}
            case ECLIPSE->{Location center=aimGround(p,12);if(center==null)return noTarget(p);show(c,center,new Vector(0,0,1),new DarkVfx.Eclipse(p.getUniqueId().getLeastSignificantBits()^tick),null);later(c,25,()->{for(var target:enemies(c,center,7))if(hit(c,target,base,true,false,false)&&!target.isDead())curse(c,target,DarkControlEvent.Kind.HEALING,.2,80);});for(int offset:new int[]{45,85,125})later(c,offset,()->{for(var target:enemies(c,center,7))hit(c,target,base*2/13,false,false,false);});}
        }
        applySlows();return true;
    }
    private LivingEntity attacker(EntityDamageEvent e){if(!(e instanceof EntityDamageByEntityEvent hit))return null;return hit.getDamager() instanceof LivingEntity l?l:hit.getDamager() instanceof Projectile shot&&shot.getShooter() instanceof LivingEntity l?l:null;}
    @SuppressWarnings("deprecation")private double beforeAbsorption(EntityDamageEvent e){return Math.max(0,e.getFinalDamage()+(e.isApplicable(EntityDamageEvent.DamageModifier.ABSORPTION)?Math.max(0,-e.getDamage(EntityDamageEvent.DamageModifier.ABSORPTION)):0));}
    /** Called once after RPG armor, before Earth combines its defense cap. */
    public void mitigate(EntityDamageEvent e){if(e.isCancelled()||!(e.getEntity() instanceof Player p)||SkillDamageGuard.isTransfer(p))return;var guard=guards.get(p.getUniqueId());var a=attacker(e);if(guard==null||guard.reserved||tick>=guard.until||!valid(guard.cast)||a==null||SkillDamageGuard.isFireTick(a)||SkillDamageGuard.isPeriodic(a)||!combat.enemy(p,a))return;double before=beforeAbsorption(e);if(before<=0)return;double amount=Math.min(8,e.getDamage()*.4);if(amount<=0)return;e.setDamage(Math.max(0,e.getDamage()-amount));guard.reserved=true;pending.put(e,new Absorbed(guard,a,before));}
    @EventHandler(priority=EventPriority.MONITOR)public void accepted(EntityDamageEvent e){var absorbed=pending.remove(e);if(absorbed==null)return;var g=absorbed.guard;g.reserved=false;if(e.isCancelled()||beforeAbsorption(e)<=0||beforeAbsorption(e)>=absorbed.before)return;guards.remove(g.cast.source.getUniqueId(),g);g.anchor.triggered=true;g.anchor.end=local(g.cast.source.getLocation(),g.cast.facing,absorbed.attacker.getEyeLocation());V at=local(g.cast.source.getLocation(),g.cast.facing,absorbed.attacker.getLocation());V delta=new V(at.x(),0,at.z()).unit();g.anchor.impact=new V(delta.x()*.4,1.1,delta.z()*.4);if(absorbed.attacker.getWorld().equals(g.cast.source.getWorld())&&absorbed.attacker.getLocation().distanceSquared(g.cast.source.getLocation())<=64&&combat.enemy(g.cast.source,absorbed.attacker))curse(g.cast,absorbed.attacker,DarkControlEvent.Kind.OUTGOING_DAMAGE,.1,40);}
    private void crossing(LivingEntity target,Location from,Location to){if(from==null||to==null||!from.getWorld().equals(to.getWorld())||from.distanceSquared(to)>256)return;for(var field:new ArrayList<>(curtains)){if(field.until<=tick||!valid(field.cast)||field.hit.contains(target.getUniqueId())||!target.getWorld().equals(field.center.getWorld())||!combat.enemy(field.cast.source,target))continue;Vector a=from.toVector().subtract(field.center.toVector()),b=to.toVector().subtract(field.center.toVector());double first=a.dot(field.cast.facing),second=b.dot(field.cast.facing),denominator=first-second;if(first*second>0||Math.abs(denominator)<.0001)continue;double t=first/denominator;if(t<0||t>1)continue;Vector at=a.clone().add(b.subtract(a).multiply(t));double width=Math.abs(at.getX()*field.cast.facing.getZ()-at.getZ()*field.cast.facing.getX());double height=at.getY()+.8;if(width>3.3||height<0||height>3)continue;double damage=field.cast.talent.getEffectDouble(field.cast.rank,"baseDamage",4);if(hit(field.cast,target,damage,true,false,false)){field.hit.add(target.getUniqueId());curse(field.cast,target,DarkControlEvent.Kind.SLOW,.25,40);field.anchor.pulse=5;field.anchor.impact=new V(at.getX()*field.cast.facing.getZ()-at.getZ()*field.cast.facing.getX(),at.getY(),0);}}
    }
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void playerMove(PlayerMoveEvent e){if(!(e instanceof PlayerTeleportEvent))crossing(e.getPlayer(),e.getFrom(),e.getTo());}
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void mobMove(io.papermc.paper.event.entity.EntityMoveEvent e){crossing(e.getEntity(),e.getFrom(),e.getTo());}
    void tick(){tick++;
        for(var job:new ArrayList<>(jobs)){if(!valid(job.cast)){jobs.remove(job);continue;}if(job.at<=tick){jobs.remove(job);try{job.action.run();}catch(RuntimeException e){cancel(job.cast.source);plugin.getLogger().warning("Dark cast cancelled: "+job.cast.talent.getId()+": "+e.getMessage());}}}
        curtains.removeIf(f->f.until<=tick||!valid(f.cast));for(var f:curtains)if(f.anchor.pulse>0)f.anchor.pulse--;
        echoes.values().removeIf(e->e.until<tick||!valid(e.cast)||e.target.isDead()||!e.target.isValid()||!e.target.getWorld().equals(e.cast.source.getWorld()));guards.values().removeIf(g->g.until<=tick||!valid(g.cast));summons.values().removeIf(s->s.until<=tick||!valid(s.cast));for(var s:summons.values())if(s.anchor.pulse>0)s.anchor.pulse--;
        curses.values().removeIf(c->c.until<=tick||!valid(c.cast)||c.target.isDead()||!c.target.isValid()||!c.target.getWorld().equals(c.cast.source.getWorld()));applySlows();
        following.removeIf(f->{boolean ended=f.until<=tick||!valid(f.cast)||f.target.isDead()||!f.target.isValid()||!f.target.getWorld().equals(f.origin.getWorld());if(ended)stop(f.visual);return ended;});for(var f:following){f.anchor.offset=v(f.target.getLocation()).sub(v(f.origin));V d=local(f.target.getLocation(),f.facing,f.target.getLocation().add(facing(f.target)));f.anchor.yaw=Math.atan2(d.x(),d.z());}
        glyphs.entrySet().removeIf(e->{var f=e.getValue();int layers=brands.layers(e.getKey().owner,e.getKey().target,tick);f.anchor.layers=layers;if(layers==0||f.target.isDead()||!f.target.isValid()||!valid(f.cast)){stop(f.visual);following.remove(f);return true;}return false;});
        if(tick%20==0){brands.prune(tick);var fx=plugin.getVfxService();if(fx!=null)visuals.values().forEach(ids->ids.removeIf(id->!fx.runtime().active(id)));visuals.values().removeIf(Set::isEmpty);}
    }
    public void cancel(Player p){UUID id=p.getUniqueId();jobs.removeIf(j->j.cast.source.equals(p));curtains.removeIf(f->f.cast.source.equals(p));echoes.entrySet().removeIf(e->e.getKey().owner.equals(id)||e.getKey().target.equals(id));guards.remove(id);summons.remove(id);curses.values().removeIf(c->c.cast.source.equals(p)||c.target.equals(p));applySlows();brands.owner(id);brands.target(id);following.removeIf(f->{if(f.cast.source.equals(p)||f.target.equals(p)){stop(f.visual);return true;}return false;});glyphs.entrySet().removeIf(e->e.getKey().owner.equals(id)||e.getKey().target.equals(id));var ids=visuals.remove(id);if(ids!=null)ids.forEach(this::stop);pending.entrySet().removeIf(e->e.getValue().guard.cast.source.equals(p));}
    public void clear(){jobs.clear();curtains.clear();echoes.clear();guards.clear();summons.clear();curses.clear();slowed.values().forEach(motion::clear);slowed.clear();applied.clear();brands.clear();following.clear();glyphs.clear();pending.clear();visuals.values().forEach(ids->ids.forEach(this::stop));visuals.clear();}
    public void shutdown(){if(task!=null){task.cancel();task=null;}clear();}
    @EventHandler public void quit(PlayerQuitEvent e){cancel(e.getPlayer());}
    @EventHandler public void death(EntityDeathEvent e){if(e.getEntity() instanceof Player p)cancel(p);brands.target(e.getEntity().getUniqueId());}
    @EventHandler public void world(PlayerChangedWorldEvent e){cancel(e.getPlayer());}
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void entityTeleport(EntityTeleportEvent e){
        if(e.getTo()!=null&&!e.getFrom().getWorld().equals(e.getTo().getWorld())&&e.getEntity() instanceof LivingEntity target){
            brands.target(target.getUniqueId());curses.values().removeIf(c->c.target.equals(target));echoes.entrySet().removeIf(x->x.getKey().target.equals(target.getUniqueId()));
            following.removeIf(f->{if(f.target.equals(target)){stop(f.visual);return true;}return false;});glyphs.entrySet().removeIf(x->x.getKey().target.equals(target.getUniqueId()));applySlows();
        }
    }
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void teleport(PlayerTeleportEvent e){if(!internalStep(e.getPlayer())&&!(plugin.getTalentSkillManager()!=null&&plugin.getTalentSkillManager().getFrost()!=null&&plugin.getTalentSkillManager().getFrost().internalStep(e.getPlayer()))&&!(plugin.getTalentSkillManager()!=null&&plugin.getTalentSkillManager().getEarth()!=null&&plugin.getTalentSkillManager().getEarth().internalRush(e.getPlayer())))cancel(e.getPlayer());}
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void mode(PlayerGameModeChangeEvent e){cancel(e.getPlayer());}
}
